from typing import List

def factorize(n: int) -> List[int]:
    if n < 2:
        return [n] if n != 0 else []

    factors = []
    divisor = 2
    while divisor <= n:
        if n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        else:
            divisor += 1 if divisor == 2 else 2  # Increment by 2 for odd numbers, 1 for 2

    return factors
