        raise ValueError("Base must be between 2 and 9")

    if x == 0:
        return '0'

    result = ''
    while x > 0:
        remainder = x % base
        if remainder < 10:
            result = str(remainder) + result
        else:
            result = 'A' + result  # 'A' for base 10 and above
        x = x // base

